---@class CumulativeRechargeMgr
local  CumulativeRechargeMgr = {}

function CumulativeRechargeMgr:Init()
    self:CleanProperty()
    self.settingMgr = SettingMgr:GetInstance()
    self:InitConfData()
    self:InitServersData()
end

function CumulativeRechargeMgr:Delete()
    self:CleanProperty()
end

------------ InitData ------------

function CumulativeRechargeMgr:CleanProperty()
    self.settingMgr = nil
    self.numRewardList = nil
    self.listRechargeValue = nil -- 累充列表数据(配表序列)
    self.listRewardAcquired = nil
    self.vCurRechargeValue = nil
    self.listRechargeItem = nil
end

function CumulativeRechargeMgr:InitServersData()
    --- 获取当前的充值进度
    self.vCurRechargeValue = 0
    --- 获取当前的领取列表
    self.listRewardAcquired = {}
    --self:RefreshServersData()
end

function CumulativeRechargeMgr:InitConfData()
    self:GetTotalLevelList()
end

function CumulativeRechargeMgr:GetTotalLevelList()
    self.listRechargeValue = {}
    local tableFile = self.settingMgr:Get(AutoIds.IdSetting1801)
    for i, row in pairs(tableFile) do
        local listData = {
            id =  parse_number(row, "id"),
            amount = parse_number(row, "amount")
        }
        table.insert(self.listRechargeValue, listData)
    end
    table.sort(self.listRechargeValue, function(a, b)
        return a.amount < b.amount
    end)
end

------------ InitData ------------

function CumulativeRechargeMgr:GetRechargeId(pAmount)
    for i, lvData in pairs(self.listRechargeValue) do
        if lvData.amount == pAmount then
            return lvData.id
        end
    end
end

function CumulativeRechargeMgr:GetRechargeAmount(pLv)
    for i, lvData in pairs(self.listRechargeValue) do
        if checkNumber(lvData.id) == checkNumber(pLv) then
            return lvData.amount
        end
    end
end

function CumulativeRechargeMgr:GetLevelData(rechargeLevel)
    local listLevelReward = {} -- {{ goodsId, num }}
    ---@type TableML.TableFile
    local tableFile = SettingMgr:GetInstance():Get(AutoIds.IdSetting1801)
    ---@type TableML.TableFileRow
    local row = tableFile:GetByPrimaryKey(rechargeLevel)
    if not IsNull(row) then
        local strPayRewardIds = string.split(parse_string(row, "reward"), ";")
        for i, v in ipairs(strPayRewardIds) do
            table.insert(listLevelReward, { goodsId = checkNumber(v) })
        end
        local strPayRewardNums = string.split(parse_string(row, "rewardNum"), ";")
         for i, v in ipairs(strPayRewardNums) do
            listLevelReward[i].num = checkNumber(v)
        end
    end
    return listLevelReward
end

function CumulativeRechargeMgr:GetSpineIdByLevel(rechargeLevel)
    ---@type TableML.TableFile
    local tableFile = SettingMgr:GetInstance():Get(AutoIds.IdSetting1801)
    ---@type TableML.TableFileRow
    local row = tableFile:GetByPrimaryKey(rechargeLevel)
    return CS.ParseUtils.ParseString(row, "spineId")
end

function CumulativeRechargeMgr:GetSceneIdByLevel(rechargeLevel)
    ---@type TableML.TableFile
    local tableFile = SettingMgr:GetInstance():Get(AutoIds.IdSetting1801)
    ---@type TableML.TableFileRow
    local row = tableFile:GetByPrimaryKey(rechargeLevel)
    return CS.ParseUtils.ParseString(row, "sceneId")
end


function CumulativeRechargeMgr:GetMainRewardsByLevel(rechargeLevel)
    local rewardsList = self:GetLevelData(rechargeLevel)
    return checkTable(rewardsList)[1]
end

function CumulativeRechargeMgr:GetSubRewardsByLevel(rechargeLevel)
    local rewardsList = clone(self:GetLevelData(rechargeLevel))
    table.remove(rewardsList, 1)
    return rewardsList
end

function CumulativeRechargeMgr:GetCurRechargeValue()
    return self.vCurRechargeValue
end

function CumulativeRechargeMgr:GetRechargeCoinGoodData()
    return GoodsConfMgr:GetInstance():GetGoodsVoById(Constants.Currency.FreeDiamondId)
end

function CumulativeRechargeMgr:GetCurRechargeLevel()
    for i, v in ipairs(self.listRechargeValue) do
        if checkNumber(self.vCurRechargeValue) < v.amount then
            if i == 1 then return 0 end
            return self.listRechargeValue[i - 1].id
        end
        if i >= #self.listRechargeValue then
            return v.id
        end
    end
end

function CumulativeRechargeMgr:InsertToRewardAcquired(pId)
    if isNull(self.listRewardAcquired)   then
        self.listRewardAcquired = {}
    end
    if pId then
        -- 领取指定奖励
        if not self:GetRewardAcquiredState(pId) then
            table.insert(self.listRewardAcquired, pId)
        end
    else
        -- 领取全部奖励
        local listRechargeValue = self.listRechargeValue
        local curValue = self:GetCurRechargeValue()
        for _, v in pairs(listRechargeValue) do
            if curValue >= checkInt(v.amount) and not self:GetRewardAcquiredState(pId) then
                table.insert(self.listRewardAcquired, v.id)
            end
        end
    end

    if self:GetDialogRef() then
        self:GetDialogRef():RefreshDialog()
    end
end

function CumulativeRechargeMgr:GetRewardAcquiredState(pId)
    for i, rewardId in ipairs(self.listRewardAcquired) do
        if checkNumber(pId) == checkNumber(rewardId) then
            return true
        end
    end
    return false
end

function CumulativeRechargeMgr:RefreshListRecharge()
    self.listRechargeItem = {}
    local listRechargeValue = self.listRechargeValue
    for i, data in pairs(listRechargeValue) do
        table.insert(self.listRechargeItem, data)
    end
end

